const keyframes = [
  { t: 0,    q: 0,    sx: 1,    belly: 0,    lean: 0,     pitch: 0,     yaw: 0,    roll: 0,     lift: 0,    shift: 0,     headX: 1,    arms: 0    },
  { t: 180,  q: 1,    sx: 1.12, belly: 0.08, lean: 0,     pitch: 0,     yaw: 0,    roll: 0,     lift: 0,    shift: 0,     headX: 1.03, arms: 0.12 },
  { t: 340,  q: 0,    sx: 0.98, belly: 0,    lean: 0,     pitch: -0.34, yaw: 0.65, roll: -0.18, lift: 0.14, shift: 0.15,  headX: 0.84, arms: 0    },
  { t: 520,  q: 0,    sx: 1,    belly: 0,    lean: 0,     pitch: 0,     yaw: 0,    roll: 0,     lift: 0,    shift: 0,     headX: 1,    arms: 0    },
