const animatedProperties = ['q', 'sx', 'belly', 'lean', 'pitch', 'yaw', 'roll', 'lift', 'shift', 'headX', 'arms'];
const pose = {};

function samplePose(t) {
  const phase = ((t % 1220) + 1220) % 1220;
  let index = keyframes.length - 1;

  for (let i = 0; i < keyframes.length - 1; i++) {
    if (phase >= keyframes[i].t && phase < keyframes[i + 1].t) {
      index = i;
      break;
    }
  }

  const a = keyframes[index];
  const b = keyframes[(index + 1) % keyframes.length];
  const end = index === keyframes.length - 1 ? 1220 : b.t;
  let u = (phase - a.t) / (end - a.t);
  u = u * u * (3 - 2 * u);

  for (const property of animatedProperties) {
    pose[property] = THREE.MathUtils.lerp(a[property], b[property], u);
