function verticalPosition(y, q) {
  return y - q * (
    0.10 * y +
    0.10 * THREE.MathUtils.smoothstep(y, 0.4, 1.4) +
    0.285 * THREE.MathUtils.smoothstep(y, 2.0, 5.36)
