function poseMesh(entry, p) {
  const position = entry.mesh.geometry.getAttribute('position');
  const output = position.array;
  const base = entry.base;
  const depthScale = 1 + (p.sx - 1) * 0.45 + p.q * 0.025;
  const pivotY = verticalPosition(3.15, p.q);
  const pivotX = p.lean * THREE.MathUtils.smoothstep(3.15, 0.8, 5.2);
  const pivotZ = 0.75 * depthScale;
  const armSide = entry.part === 'left-arm' ? -1 : entry.part === 'right-arm' ? 1 : 0;

  for (let i = 0; i < base.length; i += 3) {
    const x = base[i];
    const y = base[i + 1];
    const z = base[i + 2];

    const bellyBulge = p.belly *
      THREE.MathUtils.smoothstep(y, 0.7, 1.4) *
      (1 - THREE.MathUtils.smoothstep(y, 2.65, 3.55));

    let xx = x * (p.sx + bellyBulge);
    let yy = verticalPosition(y, p.q);
    let zz = z * depthScale;

    xx += p.lean * THREE.MathUtils.smoothstep(y, 0.8, 5.2);

    if (armSide !== 0) {
      xx += armSide * p.arms * (1 - THREE.MathUtils.smoothstep(y, 1.8, 3.8));
    }

    const headWeight = THREE.MathUtils.smoothstep(y, 3.10, 3.24);
