      const sy = Math.sin(yaw);
      const relativeZ = hz - pivotZ;
      const yawX = hx * cy + relativeZ * sy;
      hz = pivotZ - hx * sy + relativeZ * cy;
      hx = yawX;

      const pitch = p.pitch * headWeight;
      const cp = Math.cos(pitch);
      const sp = Math.sin(pitch);
      const pitchY = hy * cp - hz * sp;
      hz = hy * sp + hz * cp;
      hy = pitchY;

      const roll = p.roll * headWeight;
      const cr = Math.cos(roll);
      const sr = Math.sin(roll);
      const rollX = hx * cr - hy * sr;
      hy = hx * sr + hy * cr;
      hx = rollX;

      xx = pivotX + hx + p.shift * headWeight;
      yy = pivotY + hy + p.lift * headWeight;
      zz = hz;
    }

    output[i] = xx;
    output[i + 1] = yy;
    output[i + 2] = zz;
